const body = $json.body ?? $json;
const action = body.action || 'run_lifecycle';
const routes = {
  run_lifecycle: ['tool_job_intake','tool_drive_assets','tool_request_analysis'],
  dry_run_full_lifecycle: ['tool_job_intake','tool_drive_assets','tool_request_analysis','tool_content_planning','tool_content_generation','tool_qa_delivery'],
  create_job: ['tool_job_intake','tool_drive_assets','tool_request_analysis'],
  attach_drive_folder: ['tool_job_intake','tool_drive_assets'],
  analyse_request: ['tool_request_analysis'],
  generate_plan: ['tool_content_planning'],
  run_plan: [],
  continue_plan: [],
  generate_outputs: ['tool_content_generation'],
  qa_delivery: ['tool_qa_delivery'],
  log_progress: ['tool_logging'],
  report_error: ['tool_logging'],
  retry: ['tool_logging'],
  pause: ['tool_logging'],
  resume: ['tool_logging'],
  cancel: ['tool_logging']
};
const desired = routes[action] || routes.run_lifecycle;
const lifecycle = ['intake','drive_assets','request_analysis','analysis_approval_gate','content_planning','plan_approval_gate','content_generation','qa_delivery','final_approval_gate','delivery_pack'];
return [{json: {...body, action, mode: body.mode || 'dry_run', desired_tools: desired, lifecycle, current_stage: 'orchestrator_start', payload: body.payload || body, tool_results: [], status: 'orchestrating', plan_driven: ['run_plan','continue_plan'].includes(action)}}];

const base = $node['Authenticate And Plan Route'].json;
const row = $json;
let planPayload = {};
let selectedTools = [];
if (base.plan_driven) {
  try { planPayload = JSON.parse(row.plan_payload_json || '{}'); } catch {}
  try { selectedTools = JSON.parse(row.selected_tools_json || '[]'); } catch {}
}
const activeToolIds = ['tool_job_intake','tool_drive_assets','tool_request_analysis','tool_content_planning','tool_content_generation','tool_qa_delivery','tool_logging'];
const plannedTools = selectedTools.map(tool => tool.tool_id || tool.workflow_name).filter(Boolean);
const desired = base.plan_driven ? plannedTools.filter(tool => activeToolIds.includes(tool)) : base.desired_tools;
const missingPlan = base.plan_driven && !row.plan_id;
const results = missingPlan ? [...(base.tool_results || []), {tool: 'ai_content_orchestrator', status: 'blocked_missing_plan', reason: 'No active stored tool execution plan found'}] : base.tool_results;
const output = {...base, desired_tools: desired, missing_plan: missingPlan, status: missingPlan ? 'blocked_missing_plan' : base.status, tool_results: results};
if (base.plan_driven) {
  output.plan_id = row.plan_id || base.plan_id;
  output.approval_policy = row.approval_policy || base.approval_policy;
  output.tool_execution_plan = planPayload;
}
return [{json: output}];
